from decimal import Decimal, ROUND_HALF_EVEN

CENT = Decimal("0.01")


def tax_total(net_amounts, rate):
    """Return the invoice tax in currency units using half-even rounding."""
    if not isinstance(rate, Decimal) or not Decimal("0") <= rate <= Decimal("1"):
        raise ValueError("rate must be a Decimal between zero and one")
    amounts = list(net_amounts)
    for amount in amounts:
        if not isinstance(amount, Decimal) or amount < 0:
            raise ValueError("net amounts must be nonnegative Decimals")
    taxable = sum(amounts, Decimal("0"))
    return (taxable * rate).quantize(CENT, rounding=ROUND_HALF_EVEN)


def invoice_totals(net_amounts, rate):
    amounts = list(net_amounts)
    subtotal = sum(amounts, Decimal("0"))
    tax = tax_total(amounts, rate)
    return {"subtotal": subtotal, "tax": tax, "total": subtotal + tax}
